window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[215]={"id":"215","numero":215,"titre":"Purpuras chez l'enfant et chez l'adulte","objectifs":[{"id":"215-1","rang":"A","rubrique":"Définition","titre":"Savoir définir et reconnaître un purpura","contenu":"<p>Le <span class=\"kw-def\">purpura</span> est une <span class=\"kw-clinique\">lésion</span> cutanée ou muqueuse liée à une <span class=\"kw-def\">extravasation de sang dans le derme ou le chorion</span>, spontanée ou consécutive à un traumatisme minime. Son diagnostic est <strong>exclusivement clinique</strong>.</p>\n      <p>Cinq traits sémiologiques permettent de le reconnaître :</p>\n      <table >\n        <thead><tr><th>Trait sémiologique</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Couleur</strong></td><td><span class=\"kw-clinique\">Lésions rouges ou violacées</span>, séparées par un intervalle de peau saine</td></tr>\n          <tr><td><strong>Vitropression</strong></td><td><span class=\"kw-clinique\">Ne s'efface pas à la vitropression</span> — signe sémiologique clé qui distingue le <span class=\"kw-clinique\">purpura</span> de l'érythème</td></tr>\n          <tr><td><strong>Palpation</strong></td><td><span class=\"kw-clinique\">Maculeux</span> (non palpable) ou <span class=\"kw-clinique\">palpable</span> (infiltré) — l'aspect infiltré oriente le mécanisme</td></tr>\n          <tr><td><strong>Taille</strong></td><td>Variable, de la <span class=\"kw-clinique\">pétéchie</span> punctiforme à la nappe ecchymotique</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>Disparition sans séquelle en quelques jours, en passant par <span class=\"kw-clinique\">les</span> couleurs de la biligénie locale</td></tr>\n        </tbody>\n      </table>\n      <p>Quatre <strong>types de <span class=\"kw-clinique\">purpura</span></strong> sont à distinguer selon l'aspect des lésions :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Taille</th><th>Topographie</th><th>Couleur / aspect</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Pétéchial</span></td><td><span class=\"kw-chiffre\">1 à 4 mm</span></td><td>Membres inférieurs ++</td><td>Punctiforme, en « tête d'épingle » ; le plus fréquent</td></tr>\n          <tr><td><span class=\"kw-clinique\">Vibices</span></td><td>Linéaire</td><td>Plis de flexion, zones de friction ou de traction</td><td>Traînées linéaires ; plus rares</td></tr>\n          <tr><td><span class=\"kw-clinique\">Ecchymotique</span></td><td><span class=\"kw-chiffre\">&gt; 1 cm</span></td><td>Variable</td><td>Nappes bleu violacé aux contours mal limités</td></tr>\n          <tr><td><span class=\"kw-alerte\">Nécrotique</span></td><td>Variable</td><td>Variable</td><td><span class=\"kw-clinique\">Pétéchies</span> ou ecchymoses surélevées par une zone de nécrose</td></tr>\n        </tbody>\n      </table>\n      <figure>\n        <img src=\"../assets/images/215/purpura-petechial.png\" alt=\"Purpura pétéchial — lésions punctiformes des membres inférieurs\">\n        <figcaption><span class=\"kw-clinique\">Purpura</span> pétéchial — lésions punctiformes des membres inférieurs.</figcaption>\n      </figure>\n      <figure>\n        <img src=\"../assets/images/215/purpura-vibices.png\" alt=\"Vibices — traînées purpuriques linéaires le long des plis\">\n        <figcaption>Vibices — traînées purpuriques linéaires le long des plis.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\">⚠️ <strong>Image à compléter.</strong> La photographie du <span class=\"kw-clinique\">purpura ecchymotique</span> n'est pas disponible dans le dossier source (seules <span class=\"kw-clinique\">les</span> photos pétéchial et vibices ont pu être intégrées) — à compléter manuellement.</div>\n      <p>Le <span class=\"kw-clinique\">purpura</span> doit être distingué d'autres lésions cutanées rouges :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Différence cliniquement décisive</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Érythème</span></td><td>Dilatation vasculaire dermique — <strong>s'efface à la vitropression</strong></td></tr>\n          <tr><td>Angiome</td><td>Tumeur vasculaire — s'efface partiellement à la vitropression</td></tr>\n          <tr><td>Télangiectasie</td><td>Vaisseau ectasique en branche d'arbre mort ou étoilé — s'efface à la vitropression</td></tr>\n          <tr><td>Maladie de Kaposi</td><td>Lésions violacées ou brunâtres, nodulaires, souvent associées à un lymphœdème des membres inférieurs</td></tr>\n          <tr><td>Piqûres de puces</td><td>Lésions centrées par un point noir</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong><span class=\"kw-clinique\">Évolution</span> — biligénie locale.</strong> <span class=\"kw-clinique\">Les</span> lésions passent par toutes les couleurs : <span class=\"kw-clinique\">rouge → violet-bleu → vert-jaune → chamois</span>. La répétition de lésions sur un même site peut laisser une dyschromie brunâtre (dermite ocre) ou des cicatrices blanchâtres.</div>","frequence":3},{"id":"215-2","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir différencier un purpura vasculaire d’un purpura thrombopénique","contenu":"<p>C'est l'objectif <strong>central</strong> de l'item. Devant tout <span class=\"kw-clinique\">purpura</span>, l'examen clinique seul oriente vers l'un des <strong>quatre grands mécanismes</strong>. La distinction <span class=\"kw-etio\">hématologique</span> (thrombopénie) ↔ <span class=\"kw-etio\">vasculaire</span> (<span class=\"kw-clinique\">vascularite</span>) est la plus rentable en QCM.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Hématologique<br>(thrombopénie / thrombopathie)</th><th>Vasculaire<br>(vascularite / immuno)</th><th><span class=\"kw-etio\">Thrombotique</span><br>(<span class=\"kw-alerte\">CIVD</span>, SAPL…)</th><th>Fragilité capillaire<br>(Bateman, scorbut)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td>Trouble de l'<span class=\"kw-def\">hémostase primaire</span></td>\n            <td>Pathologie de la <span class=\"kw-def\">paroi vasculaire</span></td>\n            <td><span class=\"kw-def\">Microthromboses</span> / embolies</td>\n            <td><span class=\"kw-def\">Fragilité capillaire</span> constitutionnelle ou <span class=\"kw-etio\">acquise</span></td>\n          </tr>\n          <tr>\n            <td><strong>Aspect</strong></td>\n            <td><span class=\"kw-clinique\">Monomorphe</span> : pétéchial ++ si thrombopénie ; ecchymotique ++ si thrombopathie</td>\n            <td><span class=\"kw-clinique\">Polymorphe</span>, pétéchial, aigu, par poussées ; <span class=\"kw-clinique\">livedo</span> réticulaire</td>\n            <td>Monomorphe, pétéchial ; <span class=\"kw-clinique\">livedo</span> racemosa</td>\n            <td>Ecchymotique, chronique</td>\n          </tr>\n          <tr>\n            <td><strong>Palpation</strong></td>\n            <td><span class=\"kw-clinique\">Maculeux</span></td>\n            <td><span class=\"kw-alerte\">Infiltré</span> (maculo-papuleux)</td>\n            <td><span class=\"kw-alerte\">Infiltré</span></td>\n            <td>Non infiltré</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Nécrose</span></strong></td>\n            <td>Non</td>\n            <td>Oui ±</td>\n            <td><span class=\"kw-alerte\">Oui</span> — composante nécrotique nette</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>Diffus, prédomine en zones déclives</td>\n            <td>Zones déclives, <span class=\"kw-clinique\">aggravé par l'orthostatisme</span></td>\n            <td>Variable</td>\n            <td>Non déclive ; zones de frottement</td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte muqueuse</strong></td>\n            <td><span class=\"kw-alerte\">Oui</span> possible (gingivorragies, épistaxis)</td>\n            <td>Non</td>\n            <td>Non</td>\n            <td>Oui — gingivorragies dans le <span class=\"kw-etio\">scorbut</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">hémorragique</span></span></strong></td>\n            <td><span class=\"kw-clinique\">Oui</span></td>\n            <td>Non</td>\n            <td>Non</td>\n            <td>Gingivorragies (scorbut)</td>\n          </tr>\n          <tr>\n            <td><strong>Signes extra-cutanés</strong></td>\n            <td>Non</td>\n            <td><span class=\"kw-alerte\">Oui ⚠️</span> — arthralgies, atteinte rénale, neuropathie</td>\n            <td><span class=\"kw-alerte\">Oui</span></td>\n            <td>Non</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège classique.</strong> Un <span class=\"kw-clinique\">purpura</span> <span class=\"kw-alerte\">infiltré et palpable</span> oriente fortement vers une <span class=\"kw-etio\">vascularite</span> (mécanisme vasculaire), même en l'absence d'atteinte extra-cutanée. Le purpura <span class=\"kw-etio\">thrombopénique</span> reste <span class=\"kw-clinique\">maculeux</span> (non palpable).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie · 193 — <span class=\"kw-clinique\">Vascularite</span> systémique · 194 — Lupus - SAPL · 216 — <span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">hémorragique</span></span></em></p>","frequence":5},{"id":"215-3","rang":"A","rubrique":"Identifier une urgence","titre":"Apprécier la gravité d’un purpura","contenu":"<p>Devant tout <span class=\"kw-clinique\">purpura</span>, et quelle que soit la tranche d'âge, <strong>trois situations d'<span class=\"kw-alerte\">urgence</span></strong> doivent être reconnues immédiatement :</p>\n      <table >\n        <thead><tr><th>Urgence</th><th>Définition / critères</th><th><span class=\"kw-alerte\">Drapeaux rouges</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Purpura fulminans</span></td>\n            <td><span class=\"kw-clinique\">Sepsis</span> grave à <span class=\"kw-etio\">méningocoque</span> ++ ; rapidement extensif ; <span class=\"kw-alerte\">≥ 1 élément nécrotique ou ecchymotique ≥ 3 mm</span></td>\n            <td><span class=\"kw-clinique\">Fièvre</span> élevée ; frissons ; <span class=\"kw-alerte\">extrémités froides</span> ; <span class=\"kw-alerte\">marbrures</span> ; <span class=\"kw-bio\">TRC ≥ 3 s</span> ; <span class=\"kw-clinique\">tachycardie</span> ; hypotension</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Thrombopénie profonde</span></td>\n            <td><span class=\"kw-bio\">PQ &lt; 20 G/L</span> (souvent <span class=\"kw-bio\">&lt; 10 G/L</span>) ; risque <span class=\"kw-etio\">hémorragique</span> majeur</td>\n            <td><span class=\"kw-alerte\">Bulles hémorragiques intrabuccales</span> ; gingivorragies spontanées ; <span class=\"kw-bio\">hématurie</span> macroscopique ; <span class=\"kw-alerte\">céphalées + signes méningés</span> (hémorragie intracrânienne) ; syndrome anémique aigu</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">CIVD / vascularites systémiques</span></td>\n            <td><span class=\"kw-etio\">Microthromboses</span> + <span class=\"kw-alerte\">défaillance</span> multiviscérale potentielle</td>\n            <td>Composante nécrotique nette ; <span class=\"kw-clinique\">livedo</span> racemosa ; <span class=\"kw-etio\">SAPL catastrophique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Chez l'enfant, quatre situations pédiatriques imposent une orientation diagnostique rapide :</p>\n      <table >\n        <thead><tr><th>Situation pédiatrique</th><th>Évoquer</th><th>Drapeau clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Méningococcémie</span></td>\n            <td><span class=\"kw-alerte\">Purpura fulminans</span></td>\n            <td><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-alerte\">≥ 1 élément nécrotique ≥ 3 mm</span></td>\n          </tr>\n          <tr>\n            <td>Hémopathie maligne</td>\n            <td><span class=\"kw-etio\">LAL / LAM</span> ; métastases médullaires</td>\n            <td><span class=\"kw-clinique\">AEG</span> récente ; syndrome <span class=\"kw-etio\">tumoral</span> (ADP, HSM, douleurs osseuses) ; atteinte des autres lignées (anémie + neutropénie fébrile)</td>\n          </tr>\n          <tr>\n            <td>MAT (SHU)</td>\n            <td><span class=\"kw-etio\">Triade : thrombopénie + IRA + anémie hémolytique</span></td>\n            <td>Atteinte rénale ; <span class=\"kw-etio\">HTA</span> ; <span class=\"kw-clinique\">diarrhée</span> récente glairo-sanglante (<span class=\"kw-etio\">E. coli O157:H7</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">hémorragique</span></span> sévère</td>\n            <td>Quelle que soit l'étiologie</td>\n            <td><span class=\"kw-alerte\">Saignement extériorisé actif</span> ; collapsus ; hémorragie viscérale</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">🚨 <strong><span class=\"kw-alerte\">Urgence</span> vitale absolue.</strong> Devant tout <span class=\"kw-clinique\">purpura</span> <span class=\"kw-alerte\">fébrile</span> chez l'enfant, le diagnostic à éliminer en priorité est le <span class=\"kw-alerte\">purpura fulminans</span> — l'injection IV/IM de <span class=\"kw-ttt\">C3G</span> précède toute autre prise en charge (cf obj-8).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 214 — Thrombopénie · 315 — Leucémie aiguë · 216 — <span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">hémorragique</span></span></em></p>","frequence":3},{"id":"215-4","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer le diagnostic de purpura fulminas","contenu":"<p>Le <span class=\"kw-alerte\">purpura fulminas</span> est un <span class=\"kw-alerte\">sepsis grave à méningocoque</span> (<span class=\"kw-etio\">Neisseria meningitidis</span>, sérogroupes B et C principalement, plus rarement W et Y), associant un <span class=\"kw-alerte\">purpura nécrotique extensif</span> et un <span class=\"kw-alerte\">état de choc septique</span>.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lésion</span> cutanée</strong></td>\n            <td><span class=\"kw-clinique\">Purpura</span> <span class=\"kw-alerte\">rapidement extensif</span> (en minutes / heures) ; <span class=\"kw-alerte\">≥ 1 élément nécrotique ou ecchymotique ≥ 3 mm</span> ; ne s'efface pas à la vitropression</td>\n          </tr>\n          <tr>\n            <td><strong>Tableau septique</strong></td>\n            <td><span class=\"kw-clinique\">Fièvre</span> élevée ; frissons ; AEG ; <span class=\"kw-alerte\">extrémités froides</span> ; <span class=\"kw-alerte\">marbrures</span> ; <span class=\"kw-bio\">TRC ≥ 3 s</span> ; <span class=\"kw-clinique\">tachycardie</span> ; hypotension ; troubles de conscience</td>\n          </tr>\n          <tr>\n            <td><strong>Germes principaux</strong></td>\n            <td><span class=\"kw-etio\">Neisseria meningitidis</span> (<span class=\"kw-etio\">méningocoque</span>) ++ ; plus rarement <span class=\"kw-etio\">Streptococcus pneumoniae</span>, <span class=\"kw-etio\">Haemophilus influenzae</span> b</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span></strong></td>\n            <td><span class=\"kw-alerte\">Mortalité 20 à 30 %</span> malgré l'<span class=\"kw-ttt\">antibiothérapie</span> ; le <span class=\"kw-def\">pronostic</span> dépend du <strong>délai d'administration de la C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">🚨 <strong>L'élément nécrotique ou ecchymotique <span class=\"kw-chiffre\">≥ 3 mm</span> est le critère clé.</strong> Devant tout <span class=\"kw-clinique\">purpura</span> fébrile, la simple présence d'<strong>un</strong> élément de cette taille suffit à porter le diagnostic et à déclencher l'administration immédiate de <span class=\"kw-ttt\">C3G</span> — sans attendre PL, <span class=\"kw-bio\">hémoculture</span> ni avis spécialisé.</div>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège : la <span class=\"kw-clinique\">fièvre</span> peut manquer initialement</strong> chez le sujet âgé, immunodéprimé ou en tout début d'<span class=\"kw-clinique\">évolution</span>. Un <span class=\"kw-clinique\">purpura</span> nécrotique extensif rapidement progressif doit faire évoquer le diagnostic même afébrile.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite</em></p>","frequence":0},{"id":"215-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de réalisation de l’examen clinique chez un patient porteur d’un purpura","contenu":"<p>Le diagnostic de <span class=\"kw-clinique\">purpura</span> étant <strong>exclusivement clinique</strong>, l'anamnèse et l'examen physique conditionnent toute l'orientation étiologique et la recherche de gravité.</p>\n      <p><strong>Anamnèse</strong> — éléments à rechercher systématiquement :</p>\n      <table >\n        <thead><tr><th>Champ</th><th>Éléments à rechercher</th></tr></thead>\n        <tbody>\n          <tr><td><strong>ATCD familiaux</strong></td><td><span class=\"kw-etio\">Thrombopénie ou thrombopathie constitutionnelle</span> ; pathologie dysimmunitaire (<span class=\"kw-clinique\">lupus</span>, thyroïdite)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Âge ; sexe ; ethnie ; épisodes antérieurs de signes hémorragiques (interventions, traumatismes) ; <span class=\"kw-bio\">NFS</span> antérieures</td></tr>\n          <tr><td><strong>Contexte récent</strong></td><td>Infection <span class=\"kw-etio\">virale</span> ; contage infectieux ; séjour à l'étranger ; prise médicamenteuse ; statut vaccinal (<span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-ttt\">méningocoque</span>) ; vaccin récent (ROR)</td></tr>\n          <tr><td><strong>Signes hémorragiques</strong></td><td><span class=\"kw-clinique\">Épistaxis</span> ; <span class=\"kw-clinique\">gingivorragies</span> ; méno/métrorragies ; <span class=\"kw-clinique\">hématurie</span> ; <span class=\"kw-clinique\">méléna</span> ; <span class=\"kw-clinique\">rectorragies</span></td></tr>\n          <tr><td><strong>Signes d'orientation</strong></td><td><span class=\"kw-clinique\">Fièvre</span> ; arthralgies ; douleurs abdominales ; douleurs osseuses ; AEG ; <span class=\"kw-clinique\">céphalées</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Examen physique</strong> — l'examen est complet, déshabillé, à la recherche de <span class=\"kw-alerte\">signes de gravité</span> :</p>\n      <table >\n        <thead><tr><th>Élément à examiner</th><th>Recherche / signes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Lésions purpuriques</strong></td><td>Topographie ; aspect (<span class=\"kw-clinique\">pétéchial / vibices / ecchymotique / nécrotique</span>) ; caractère infiltré ou maculeux ; vitropression</td></tr>\n          <tr><td><strong>Muqueuses</strong></td><td><span class=\"kw-clinique\">Bulles hémorragiques intrabuccales</span> ; gingivorragies ; <span class=\"kw-clinique\">pétéchies</span> palatines ; conjonctives</td></tr>\n          <tr><td><strong>Hémodynamique</strong></td><td>TA ; FC ; <span class=\"kw-alerte\">TRC</span> ; <span class=\"kw-alerte\">marbrures</span> ; extrémités froides</td></tr>\n          <tr><td><strong>Syndrome <span class=\"kw-etio\">tumoral</span></strong></td><td><span class=\"kw-clinique\">ADP périphériques</span> ; HSM ; douleurs osseuses (sternum, métaphyses) ; masses</td></tr>\n          <tr><td><strong>Signes extra-cutanés</strong></td><td>Arthralgies ; douleurs abdominales ; <span class=\"kw-imagerie\">bandelette urinaire</span> (<span class=\"kw-bio\">hématurie</span> / <span class=\"kw-bio\">protéinurie</span>) ; signes neurologiques</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Signes de gravité</span></strong></td><td><span class=\"kw-alerte\">Saignement extériorisé actif</span> ; <span class=\"kw-alerte\">collapsus</span> ; <span class=\"kw-alerte\">troubles de conscience</span> ; <span class=\"kw-clinique\">céphalées</span> + signes méningés</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"215-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de prescription des examens biologiques à effectuer en urgence devant un purpura","contenu":"<p>Un <strong>bilan <span class=\"kw-ttt\">biologique</span> de 1ʳᵉ intention</strong> est systématique devant tout <span class=\"kw-clinique\">purpura</span>. Il affirme ou élimine la thrombopénie et recherche <span class=\"kw-clinique\">les</span> causes graves.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / recherche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS-plaquettes + frottis sanguin + réticulocytes</span></td><td>Affirme/élimine la thrombopénie ; cherche d'autres cytopénies ; oriente vers une hémopathie ou une MAT (schizocytes)</td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan d'hémostase</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">D-dimères</span>)</td><td>Recherche une <span class=\"kw-alerte\">CIVD</span> ; oriente vers une coagulopathie</td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan hépatique</span></td><td>Cause hépatique d'insuffisance d'hémostase</td></tr>\n          <tr><td><span class=\"kw-bio\">Groupe sanguin, Rhésus, RAI</span></td><td>Prétransfusionnel — anticipation d'une transfusion de CGR ou de <span class=\"kw-bio\">plaquettes</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Créatininémie</span> + <span class=\"kw-imagerie\">bandelette urinaire</span> (<span class=\"kw-bio\">hématurie</span> / <span class=\"kw-bio\">protéinurie</span>)</td><td>Recherche une atteinte rénale (<span class=\"kw-clinique\">vascularite</span>, MAT) ; chez l'enfant ⚠️ systématique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan orienté selon le contexte</strong> — examens complémentaires immédiats :</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Examens complémentaires immédiats</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Fièvre / état septique</span></td><td><span class=\"kw-bio\">Hémocultures</span> (avant ATB si possible) ; <span class=\"kw-bio\">CRP</span> ; PL si <span class=\"kw-alerte\">méningococcémie</span> — mais ne retarde <strong>jamais</strong> la C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span></td></tr>\n          <tr><td>Souffle cardiaque nouveau</td><td><span class=\"kw-imagerie\">ETT / ETO</span> (<span class=\"kw-clinique\">endocardite</span> d'Osler) ; <span class=\"kw-bio\">hémocultures</span> répétées</td></tr>\n          <tr><td>Syndrome abdominal / <span class=\"kw-clinique\">vomissements</span> / <span class=\"kw-clinique\">méléna</span> / ménométrorragies</td><td><span class=\"kw-imagerie\">Imagerie abdominale</span> (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">TDM</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Céphalées</span> / signes méningés</td><td><span class=\"kw-imagerie\">Imagerie cérébrale</span> (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>) + <span class=\"kw-imagerie\">fond d'œil</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation de la numération plaquettaire</strong> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-bio\">Plaquettes</span></th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 30 G/L</span></td><td>Thrombopénie imputable dans le <span class=\"kw-clinique\">purpura</span> ; ne pas négliger une cause associée (thrombose, <span class=\"kw-clinique\">vascularite</span>, embolie)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">30 – 100 G/L</span></td><td>Évoquer une <strong>consommation de <span class=\"kw-bio\">plaquettes</span></strong> par microthromboses diffuses (<span class=\"kw-clinique\">purpura</span> <span class=\"kw-etio\">thrombotique</span>, <span class=\"kw-alerte\">CIVD</span>)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 100 G/L</span></td><td>Thrombopénie non imputable dans le <span class=\"kw-clinique\">purpura</span> → rechercher une autre cause (<span class=\"kw-clinique\">vascularite</span>, embolie, thrombose)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège enfant.</strong> Chez l'enfant, la <span class=\"kw-bio\">créatininémie</span> et la <span class=\"kw-imagerie\">bandelette urinaire</span> sont <strong>systématiques</strong> devant tout <span class=\"kw-clinique\">purpura</span> — elles dépistent la <span class=\"kw-etio\">MAT (SHU)</span>, 2ᵉ <span class=\"kw-alerte\">urgence</span> après le fulminans.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie · 216 — <span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">hémorragique</span></span> · 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse</em></p>","frequence":4},{"id":"215-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de prescription des examens biologiques de première intention selon l’orientation diagnostique du purpura","contenu":"<p>Une fois le mécanisme suspecté à l'examen clinique, le bilan paraclinique de <strong>1ʳᵉ intention</strong> est ciblé selon l'orientation diagnostique.</p>\n      <table >\n        <thead><tr><th>Orientation</th><th>Bilan paraclinique de 1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Thrombopénie</span></td>\n            <td>Bilan de thrombopénie (cf item 214) ; <span class=\"kw-imagerie\">myélogramme</span> si <span class=\"kw-chiffre\">&lt; 30 G/L</span> et/ou autres cytopénies ; <span class=\"kw-bio\">sérologies VIH / VHB / VHC</span> ; <span class=\"kw-bio\">sérologies</span> <span class=\"kw-etio\">EBV</span> / CMV / Parvovirus B19 ; <span class=\"kw-bio\">test de Coombs</span> si AHAI</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Vasculaire / vascularite</span></td>\n            <td><span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">ionogramme</span> sanguin ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">protéinurie</span> sur échantillon +<span class=\"kw-chiffre\"> 24 h</span> ; sédiment urinaire ; <span class=\"kw-bio\">ANCA</span> ; <span class=\"kw-bio\">cryoglobulinémie</span> ; <span class=\"kw-bio\">électrophorèse des protéines</span> sériques ; <span class=\"kw-bio\">LDH</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">MAT (SHU, PTT)</span></td>\n            <td><span class=\"kw-imagerie\">Frottis : schizocytes</span> ; <span class=\"kw-bio\">LDH</span> élevés ; <span class=\"kw-bio\">haptoglobine</span> effondrée ; <span class=\"kw-bio\">bilirubine</span> libre élevée ; <span class=\"kw-bio\">bilan rénal</span> ; <span class=\"kw-bio\">ADAMTS13</span> (PTT)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Endocardite</span> (<span class=\"kw-clinique\">purpura</span> fébrile + souffle)</td>\n            <td><span class=\"kw-bio\">Hémocultures répétées</span> (<span class=\"kw-chiffre\">≥ 3</span> paires) ; <span class=\"kw-imagerie\">ETT puis ETO</span> ; <span class=\"kw-bio\">sérologies</span> Coxiella, Bartonella si négatives</td>\n          </tr>\n          <tr>\n            <td>Pédiatrie — séjour à l'étranger récent</td>\n            <td>Recherche de <span class=\"kw-etio\">paludisme</span> (<span class=\"kw-imagerie\">frottis + goutte épaisse</span>) ; <span class=\"kw-etio\">dengue</span> (NS1, <span class=\"kw-chiffre\">IgM</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan de 2ᵉ intention</strong> — selon le contexte et <span class=\"kw-clinique\">les</span> premiers résultats :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Myélogramme</span></td><td>Syndrome <span class=\"kw-etio\">tumoral</span> ou anomalies des autres lignées ; thrombopénie centrale suspectée</td></tr>\n          <tr><td>Bilan d'<span class=\"kw-bio\">hémostase primaire</span> (PFA-100/200, agrégation plaquettaire, FvW <span class=\"kw-bio\">antigène</span> + activité)</td><td>Hématomes fréquents, <span class=\"kw-etio\">thrombopathie</span> suspectée</td></tr>\n          <tr><td>Bilan <span class=\"kw-etio\">auto-immun</span> (<span class=\"kw-bio\">FAN</span>, anti-ADN, dosage pondéral des Ig, phénotypage lymphocytaire)</td><td><span class=\"kw-etio\">Vascularite</span> / connectivite / déficit immunitaire suspecté</td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologies CMV, EBV, VIH, VHC, Parvovirus B19</span></td><td>Cause <span class=\"kw-etio\">virale</span> suspectée</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie · 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse · 170 — <span class=\"kw-clinique\">Paludisme</span> · 194 — <span class=\"kw-clinique\">Lupus</span> - SAPL · 189 — Déficit immunitaire</em></p>","frequence":1},{"id":"215-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies de purpura dont les causes infectieuses","contenu":"<p>Objectif le plus lourd de l'item. <span class=\"kw-clinique\">Les</span> étiologies se classent selon les <strong>quatre grands mécanismes</strong> : hématologique, vasculaire (<span class=\"kw-clinique\">vascularite</span>), <span class=\"kw-etio\">thrombotique</span> et fragilité vasculaire.</p>\n\n      <p><strong>Section 1 — <span class=\"kw-clinique\">Purpura</span> hématologique (thrombopénie / thrombopathie)</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Centrale</strong> (défaut de production)</td>\n            <td><span class=\"kw-etio\">Envahissement médullaire</span> (LAL/LAM, métastases, lymphome) ; <span class=\"kw-etio\">aplasie médullaire</span> (idiopathique, <span class=\"kw-etio\">toxique</span>, médicamenteuse) ; <span class=\"kw-etio\">mégaloblastoses</span> (<span class=\"kw-bio\">carence B9/B12</span>, médicaments) ; thrombopénies constitutionnelles (Wiskott-Aldrich, MYH9) ; <span class=\"kw-etio\">alcoolisme</span> chronique ; <span class=\"kw-alerte\">SAM</span> ; <span class=\"kw-alerte\">sepsis</span> (mécanisme mixte)</td>\n          </tr>\n          <tr>\n            <td><strong>Périphérique — consommation</strong></td>\n            <td><span class=\"kw-alerte\">CIVD</span> ; <span class=\"kw-alerte\">MAT</span> (SHU, PTT) ; <span class=\"kw-alerte\">sepsis</span> ; <span class=\"kw-etio\">paludisme</span> ; prothèse valvulaire ; CEC ; <span class=\"kw-clinique\">syndrome de Kasabach</span>-Merritt</td>\n          </tr>\n          <tr>\n            <td><strong>Périphérique — destruction immuno</strong></td>\n            <td><span class=\"kw-etio\">PTI</span> (++ enfant) ; <span class=\"kw-etio\">lupus, SAPL</span> ; syndrome d'Evans (AHAI + PTI) ; LLC ; DICV ; Wiskott-Aldrich ; <span class=\"kw-etio\">viroses</span> (<span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHC</span>, VHB, EBV, CMV, Parvovirus B19, rubéole) ; allo-immune (néonatale, post-transfusionnelle)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Iatrogène</span></strong> (immuno-<span class=\"kw-etio\">allergique</span>)</td>\n            <td><span class=\"kw-alerte\">TIH (héparines)</span> ++ ; <span class=\"kw-ttt\">quinine</span> ; <span class=\"kw-ttt\">thiazidiques</span> ; <span class=\"kw-ttt\">AINS</span> ; anti-sécrétoires ; anti-arythmiques ; anti-épileptiques ; ATB (<span class=\"kw-ttt\">cotrimoxazole</span>, <span class=\"kw-ttt\">rifampicine</span>, β-lactamines)</td>\n          </tr>\n          <tr>\n            <td><strong>Thrombopathies</strong> (constitutionnelles)</td>\n            <td><span class=\"kw-etio\">Maladie de Willebrand</span> ; <span class=\"kw-etio\">Bernard-Soulier</span> (GpIb-IX) ; <span class=\"kw-etio\">Glanzmann</span> (GP2b-3a) ; déficits enzymatiques (cyclo-oxygénase, thromboxane synthétase)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Section 2 — <span class=\"kw-clinique\">Purpura</span> vasculaire par <span class=\"kw-clinique\">vascularite</span> / mécanisme immunologique</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Infectieux</span></strong></td>\n            <td>Viroses graves (<span class=\"kw-etio\">EBV</span>, CMV, VIH, hépatites, dengue, Parvovirus B19, varicelle, rougeole) ; <span class=\"kw-alerte\">sepsis</span> chronique ; <span class=\"kw-alerte\">purpura fulminans</span> ; <span class=\"kw-etio\">rickettsioses</span> (<span class=\"kw-clinique\">fièvre</span> boutonneuse méditerranéenne) ; <span class=\"kw-etio\">paludisme</span> ; <span class=\"kw-etio\">endocardite d'Osler</span> (<span class=\"kw-clinique\">purpura</span> conjonctival + sus-claviculaire, <span class=\"kw-clinique\">nodules d'Osler</span> de la face palmaire, flammèches sous-unguéales) ; <span class=\"kw-etio\">maladie de Kawasaki</span> (enfant)</td>\n          </tr>\n          <tr>\n            <td><strong>Vascularites individualisées</strong></td>\n            <td><span class=\"kw-etio\">Purpura rhumatoïde (Schönlein-Henoch)</span> = cause la plus fréquente de <span class=\"kw-clinique\">purpura</span> infiltré de l'enfant ; PAN cutanée/systémique ; <span class=\"kw-clinique\">GPA</span> ; MPA ; GEPA</td>\n          </tr>\n          <tr>\n            <td><strong>Connectivites / maladies systémiques</strong></td>\n            <td><span class=\"kw-etio\">Lupus</span> ; <span class=\"kw-clinique\">PR</span> ; Gougerot-Sjögren ; Sharp ; Behçet ; sclérodermie ; dermatomyosite ; entérocolites inflammatoires ; vascularites paranéoplasiques (cancers, hémopathies)</td>\n          </tr>\n          <tr>\n            <td><strong>Dysglobulinémies</strong></td>\n            <td><span class=\"kw-etio\">Cryoglobulinémie</span> (→ rechercher <span class=\"kw-etio\">VHC</span>, lymphoprolifération) ; <span class=\"kw-etio\">amylose AL</span> (siège cervico-palpébral évocateur) ; gammapathies monoclonales (→ rechercher une Willebrand <span class=\"kw-etio\">acquise</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> <strong>vascularites des gros vaisseaux</strong> (Horton, <span class=\"kw-clinique\">Takayasu</span>) ne donnent <strong>jamais</strong> de <span class=\"kw-clinique\">purpura</span> ⭐ — piège classique d'oral.</div>\n\n      <p><strong>Section 3 — <span class=\"kw-clinique\">Purpura</span> <span class=\"kw-etio\">thrombotique</span> (le contenu du vaisseau lèse la paroi)</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Microthromboses cutanées</strong></td>\n            <td><span class=\"kw-alerte\">CIVD</span> ; <span class=\"kw-alerte\">SAPL</span> (forme catastrophique = thromboses multiples + <span class=\"kw-alerte\">défaillance</span> multiviscérale) ; cryoglobulinémie ; cryofibrinogène ; SMP (polyglobulie, LMC, LMMC, LA) ; déficit en protéine C ou S ; traitement <span class=\"kw-ttt\">anticoagulant</span> (<span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">héparines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Embolies distales</strong></td>\n            <td>Polytraumatisme → embolies graisseuses ; <span class=\"kw-etio\">athérosclérose</span> → embolies de cristaux de <span class=\"kw-bio\">cholestérol</span> ; cardiopathie emboligène (myxome) ou artériopathie → embolies cruoriques</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Section 4 — Fragilité vasculaire sans <span class=\"kw-clinique\">vascularite</span> (« <span class=\"kw-clinique\">purpura</span> dermatologique »)</strong></p>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Purpura de Bateman</span></td>\n            <td>Taches ecchymotiques de la face dorsale des avant-bras + mains ⭐ ; peau atrophique ridée ; pseudo-cicatrices en étoile ; causes : hypercorticisme (endogène ou <span class=\"kw-etio\">iatrogène</span>), sénescence cutanée</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Scorbut</span></td>\n            <td><span class=\"kw-bio\">Carence en vitamine C</span> → guérison par apport de vit. C ; <span class=\"kw-clinique\">ecchymoses</span> + pétéchies péri-folliculaires + déchaussement dentaire + hypertrophie gingivale</td>\n          </tr>\n          <tr>\n            <td><strong>Constitutionnel</strong></td>\n            <td><span class=\"kw-etio\">Ehlers-Danlos</span> (hyperlaxité + cicatrisation anormale) ; pseudo-xanthome élastique ; fragilité capillaire idiopathique (femme jeune, <span class=\"kw-clinique\">ecchymoses</span> sur chocs minimes)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Acquis</span> divers</strong></td>\n            <td><span class=\"kw-clinique\">Purpura</span> à la pression / à l'effort (<span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">syndrome de pénétration</span>) ; capillarite chronique purpurique (insuffisance veineuse → dermite ocre)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Spécificités pédiatriques.</strong> Devant tout <span class=\"kw-clinique\">purpura</span> fébrile chez l'enfant, l'ordre des hypothèses est : (1) <span class=\"kw-alerte\">purpura fulminans</span> (<span class=\"kw-alerte\">urgence</span> vitale), (2) purpura <span class=\"kw-etio\">infectieux</span> non sévère. En dehors de la <span class=\"kw-clinique\">fièvre</span>, hiérarchie thrombopénique = <span class=\"kw-etio\">PTI ++</span> &gt; <span class=\"kw-etio\">MAT/SHU</span> &gt; cause centrale (<span class=\"kw-etio\">LAL/LAM</span>, aplasie). Pour le purpura non thrombopénique, penser au <span class=\"kw-etio\">purpura rhumatoïde ++</span> (cause la plus fréquente chez l'enfant).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie · 193 — <span class=\"kw-clinique\">Vascularite</span> systémique · 194 — Lupus - SAPL · 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse · 170 — <span class=\"kw-clinique\">Paludisme</span> · 315 — Leucémie aiguë · 189 — Déficit immunitaire · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":8},{"id":"215-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures d’urgence devant un purpura","contenu":"<p>Trois situations imposent des <strong>mesures d'<span class=\"kw-alerte\">urgence</span></strong> codifiées devant un <span class=\"kw-clinique\">purpura</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Mesures d'urgence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Suspicion de purpura fulminans</span></td>\n            <td>\n              <ul>\n                <li>Injection IM ou IV de <span class=\"kw-ttt\">C3G (ceftriaxone)</span> <span class=\"kw-alerte\">immédiate</span>, avant tout transfert et <span class=\"kw-alerte\">avant PL</span> / <span class=\"kw-bio\">hémoculture</span> si retard</li>\n                <li>Pose de 2 VVP de bon calibre, voire voie intra-osseuse en cas d'échec</li>\n                <li><span class=\"kw-alerte\">Remplissage NaCl 0,9 %</span> <span class=\"kw-chiffre\">20 mL/kg en 5 à 10 min</span></li>\n                <li>Transfert médicalisé en <span class=\"kw-alerte\">réanimation</span></li>\n                <li>Prophylaxie de l'entourage (<span class=\"kw-ttt\">rifampicine</span> ou C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> IM) après confirmation</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Syndrome hémorragique sévère</span> (toute thrombopénie)</td>\n            <td>\n              <ul>\n                <li>Compression d'un saignement actif</li>\n                <li>Pose de 2 VVP</li>\n                <li>Bilan prétransfusionnel (<span class=\"kw-bio\">groupe × 2, Rhésus, RAI</span>)</li>\n                <li>Transfusion de CGR si anémie aiguë</li>\n                <li>Transfusion de <span class=\"kw-bio\">plaquettes</span> selon le mécanisme : <strong>indiquée</strong> si thrombopénie <span class=\"kw-etio\">centrale</span> ; <strong>non indiquée</strong> si thrombopénie <span class=\"kw-etio\">périphérique</span> (PTI…), sauf hémorragie grave/neurologique/intra-abdominale/extériorisée abondante ou <span class=\"kw-ttt\">chirurgie</span> urgente</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Indications de transfusion de <span class=\"kw-bio\">plaquettes</span> en pédiatrie</td>\n            <td>\n              <ul>\n                <li>LAL traitée par <span class=\"kw-ttt\">chimiothérapie</span> : <span class=\"kw-chiffre\">&lt; 20 G/L</span></li>\n                <li>Tumeur cérébrale : <span class=\"kw-chiffre\">&lt; 50 G/L</span></li>\n                <li><span class=\"kw-etio\">PTI</span> : <strong>pas</strong> d'indication systématique, sauf hémorragie sévère</li>\n                <li>Quantité = <span class=\"kw-chiffre\">1 unité plaquettaire pour 5 kg de poids</span> ; CPA ou MCP ; irradiés si immunodéprimé ; transfusion en débit libre (attention au volume total chez le petit enfant)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">🚨 <strong>La C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> IM/IV précède tout</strong> devant une suspicion de <span class=\"kw-alerte\">purpura fulminans</span>. Pas de PL, pas d'<span class=\"kw-bio\">hémoculture</span>, pas de <span class=\"kw-imagerie\">TDM</span> cérébrale avant l'injection. Le retard d'<span class=\"kw-ttt\">antibiothérapie</span> est le principal facteur pronostique.</div>\n      <div class=\"callout callout-warn\">⚠️ <strong>PTI = pas de <span class=\"kw-bio\">plaquettes</span>.</strong> Le réflexe « <span class=\"kw-clinique\">purpura</span> + thrombopénie → transfusion de <span class=\"kw-bio\">plaquettes</span> » est faux dans le <span class=\"kw-etio\">PTI</span> : la cause étant une destruction périphérique, <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">plaquettes</span> transfusées sont détruites en quelques heures. La transfusion n'a sa place qu'en cas d'hémorragie sévère menaçante.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 214 — Thrombopénie · 329 — Transfusion sanguine · 216 — <span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">hémorragique</span></span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Purpura</span> fulminans <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> infectieuse</span></strong></p><p><span class=\"kw-ttt\">C3G (ceftriaxone)</span> IM/IV <span class=\"kw-alerte\">immédiate</span>, avant <span class=\"kw-bio\">PL</span> / <span class=\"kw-bio\">hémoculture</span> et avant transfert</p><ul><li><span class=\"kw-alerte\">Fièvre</span> + <span class=\"kw-alerte\">≥ 1 élément nécrotique ou ecchymotique ≥ 3 mm</span>, <span class=\"kw-clinique\">purpura</span> rapidement extensif</li><li><span class=\"kw-alerte\">Choc septique</span> : <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-alerte\">extrémités froides</span>, <span class=\"kw-bio\">TRC ≥ 3 s</span></li></ul><p><strong>Thrombopénie profonde <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> <span class=\"kw-etio\">hémorragique</span></span></strong></p><p><span class=\"kw-alerte\">Hospitalisation</span> ; <span class=\"kw-bio\">bilan prétransfusionnel</span> ; transfusion plaquettaire selon le mécanisme</p><ul><li><span class=\"kw-bio\">Plaquettes &lt; 20 G/L</span> (souvent <span class=\"kw-bio\">&lt; 10 G/L</span>)</li><li><span class=\"kw-alerte\">Bulles hémorragiques intrabuccales</span>, <span class=\"kw-alerte\">gingivorragies spontanées</span>, risque d'<span class=\"kw-alerte\">hémorragie intracrânienne</span></li></ul><p><strong><span class=\"kw-alerte\">CIVD</span> / MAT (SHU) <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> <span class=\"kw-etio\">thrombotique</span></span></strong></p><p>Chez l'<span class=\"kw-clinique\">enfant</span> : <span class=\"kw-bio\">créatininémie</span> + <span class=\"kw-imagerie\">bandelette urinaire</span> systématiques (<span class=\"kw-def\">dépistage</span> MAT)</p><ul><li><span class=\"kw-etio\">CIVD</span> : <span class=\"kw-alerte\">défaillance multiviscérale</span> potentielle</li><li><span class=\"kw-etio\">MAT (SHU)</span> : triade <span class=\"kw-bio\">thrombopénie + IRA + anémie hémolytique</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Fièvre + ≥ 1 élément nécrotique ou ecchymotique ≥ 3 mm</span> → <span class=\"kw-def\">purpura fulminans</span></li><li><span class=\"kw-alerte\">Marbrures</span>, <span class=\"kw-alerte\">extrémités froides</span>, <span class=\"kw-bio\">TRC ≥ 3 s</span>, <span class=\"kw-clinique\">tachycardie</span>, hypotension (<span class=\"kw-alerte\">choc septique</span>)</li><li><span class=\"kw-alerte\">Bulles hémorragiques intrabuccales</span>, <span class=\"kw-alerte\">gingivorragies spontanées</span> (thrombopénie profonde)</li><li><span class=\"kw-alerte\">Saignement extériorisé actif</span>, <span class=\"kw-clinique\">hématurie macroscopique</span>, ménométrorragies</li><li><span class=\"kw-alerte\">Céphalées + signes méningés + troubles de conscience</span> → hémorragie intracrânienne</li><li><span class=\"kw-alerte\">Syndrome abdominal aigu</span> → hémorragie viscérale</li><li><span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">syndrome tumoral</span> (ADP, HSM, douleurs osseuses) → <span class=\"kw-etio\">hémopathie</span></li><li>Atteinte <span class=\"kw-clinique\">rénale</span> + <span class=\"kw-clinique\">HTA</span> + <span class=\"kw-clinique\">diarrhée glairosanglante</span> → <span class=\"kw-etio\">MAT (SHU)</span></li></ul>","principes":"<p>Devant une suspicion de <span class=\"kw-def\">purpura fulminans</span>, la <span class=\"kw-ttt\">C3G</span> IM/IV <span class=\"kw-alerte\">précède tout</span> : pas de <span class=\"kw-bio\">PL</span>, pas d'<span class=\"kw-bio\">hémoculture</span>, pas de <span class=\"kw-imagerie\">TDM</span> avant l'injection. Le retard d'<span class=\"kw-ttt\">antibiothérapie</span> est le principal facteur pronostique.</p><p><strong>Suspicion de <span class=\"kw-alerte\">purpura fulminans</span></strong></p><ul><li><span class=\"kw-ttt\">C3G (ceftriaxone)</span> IM/IV <span class=\"kw-alerte\">immédiate</span>, avant transfert et avant <span class=\"kw-bio\">PL</span> / <span class=\"kw-bio\">hémoculture</span> si retard</li><li>Pose de <span class=\"kw-ttt\">2 VVP</span> de bon calibre, voire <span class=\"kw-ttt\">voie intra-osseuse</span> en cas d'échec</li><li><span class=\"kw-ttt\">Remplissage NaCl 0,9 %</span> <span class=\"kw-chiffre\">20 mL/kg en 5 à 10 min</span>, transfert médicalisé en <span class=\"kw-alerte\">réanimation</span></li><li>Prophylaxie de l'entourage (<span class=\"kw-ttt\">rifampicine</span> ou <span class=\"kw-ttt\">C3G IM</span>) après confirmation</li></ul><p><strong><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">hémorragique</span></span> sévère</strong></p><p><span class=\"kw-ci\">Pas de transfusion plaquettaire systématique dans le PTI</span> (<span class=\"kw-bio\">plaquettes</span> détruites en quelques heures)</p><ul><li>Compression d'un saignement actif, pose de <span class=\"kw-ttt\">2 VVP</span></li><li><span class=\"kw-bio\">Bilan prétransfusionnel</span> (groupe × 2, Rhésus, RAI) ; <span class=\"kw-ttt\">transfusion de CGR</span> si anémie aiguë</li><li>Transfusion de <span class=\"kw-ttt\">plaquettes</span> : indiquée si thrombopénie <span class=\"kw-etio\">centrale</span> ; non indiquée si thrombopénie <span class=\"kw-etio\">périphérique</span> (PTI), sauf hémorragie grave</li></ul><p><strong>Transfusion plaquettaire — pédiatrie</strong></p><ul><li><span class=\"kw-etio\">LAL</span> sous <span class=\"kw-ttt\">chimiothérapie</span> : <span class=\"kw-chiffre\">&lt; 20 G/L</span></li><li>Tumeur cérébrale : <span class=\"kw-chiffre\">&lt; 50 G/L</span></li><li>Quantité = <span class=\"kw-chiffre\">1 unité plaquettaire pour 5 kg</span> ; CPA ou MCP ; irradiés si immunodéprimé</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/hematologie-cancerologie/purpura","label":"Pedia-univ — Purpura"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-215.pdf","label":"Pilly étudiant — Pilly 2023 item 215"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Purpura : fièvre + élément nécrotique (purpura fulminans) ? — Diagnostic clinique : lésion ne s'effaçant pas à la vitropression","detail":"<h4>CAT — démarche diagnostique devant un <span class=\"kw-clinique\">purpura</span> — Réflexe initial : éliminer le <span class=\"kw-alerte\">purpura fulminans</span></h4>","branches":[{"to":"t-fulminans","label":"Oui — fièvre + ≥ 1 élément nécrotique/ecchymotique ≥ 3 mm","color":"red"},{"to":"q-nfs","label":"Non — purpura non fébrile ou sans nécrose","color":"blue"}]},{"id":"t-fulminans","kind":"terminal","label":"Purpura fulminans","color":"red","detail":"<h4>Reconnaître</h4><ul><li><span class=\"kw-alerte\">Sepsis grave à méningocoque</span> ; <span class=\"kw-clinique\">purpura</span> <span class=\"kw-alerte\">rapidement extensif</span> ; <span class=\"kw-alerte\">≥ 1 élément nécrotique ou ecchymotique ≥ 3 mm</span></li></ul><h4>Tableau septique</h4><ul><li><span class=\"kw-clinique\">Fièvre élevée</span>, <span class=\"kw-clinique\">frissons</span>, AEG</li><li><span class=\"kw-alerte\">Extrémités froides</span>, <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-bio\">TRC ≥ 3 s</span></li><li><span class=\"kw-clinique\">Tachycardie</span>, hypotension, troubles de conscience</li></ul><h4>Germes</h4><ul><li><span class=\"kw-etio\">Neisseria meningitidis</span> ++ ; plus rarement <span class=\"kw-etio\">Streptococcus pneumoniae</span>, <span class=\"kw-etio\">Haemophilus influenzae</span> b</li></ul><h4>Conduite immédiate</h4><ul><li><span class=\"kw-ttt\">C3G (ceftriaxone)</span> IM/IV <span class=\"kw-alerte\">avant PL / hémoculture / transfert</span></li><li><span class=\"kw-ttt\">2 VVP</span> (voire <span class=\"kw-ttt\">intra-osseuse</span>) + <span class=\"kw-ttt\">remplissage NaCl 0,9 %</span> <span class=\"kw-chiffre\">20 mL/kg en 5 à 10 min</span></li><li>Transfert médicalisé en <span class=\"kw-alerte\">réanimation</span> ; prophylaxie de l'entourage (<span class=\"kw-ttt\">rifampicine</span>)</li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li><span class=\"kw-alerte\">Mortalité 20 à 30 %</span> ; dépend du <span class=\"kw-chiffre\">délai d'administration de la C3G</span></li></ul><h4>Renvoi</h4><ul><li>Item 151 (<span class=\"kw-alerte\">méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span>)</li></ul>"},{"id":"q-nfs","kind":"decision","label":"Thrombopénie sur la NFS ? — NFS-plaquettes + frottis systématiques devant tout purpura","branches":[{"to":"q-mecanisme","label":"Oui — plaquettes basses","color":"amber"},{"to":"q-palpable","label":"Non — plaquettes normales (> 100 G/L)","color":"blue"}]},{"id":"q-mecanisme","kind":"decision","label":"Mécanisme de la thrombopénie ? — Myélogramme si thrombopénie profonde ou autres cytopénies","branches":[{"to":"t-centrale","label":"Autres cytopénies · syndrome tumoral · AEG","color":"red"},{"to":"t-pti","label":"Thrombopénie isolée · contexte viral / enfant","color":"amber"},{"to":"t-mat","label":"Schizocytes + IRA + anémie hémolytique","color":"red"}]},{"id":"t-centrale","kind":"terminal","label":"Thrombopénie centrale (hémopathie)","color":"red","detail":"<h4>Évoquer</h4><ul><li><span class=\"kw-clinique\">AEG récente</span>, <span class=\"kw-clinique\">syndrome tumoral</span> (ADP, HSM, douleurs osseuses), atteinte des autres lignées (<span class=\"kw-clinique\">anémie</span> + neutropénie fébrile)</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Envahissement médullaire</span> : LAL/LAM, métastases, lymphome</li><li><span class=\"kw-etio\">Aplasie médullaire</span> ; <span class=\"kw-etio\">mégaloblastose</span> (<span class=\"kw-bio\">carence B9/B12</span>)</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Myélogramme</span> indispensable</li></ul><h4>Renvoi</h4><ul><li>Item 315 (leucémie aiguë) · Item 214 (thrombopénie)</li></ul>"},{"id":"t-pti","kind":"terminal","label":"PTI / thrombopénie périphérique","color":"amber","detail":"<h4>Confirmation</h4><ul><li>Thrombopénie <span class=\"kw-bio\">isolée</span>, autres lignées normales ; <span class=\"kw-def\">PTI</span> = diagnostic d'élimination (AC anti-<span class=\"kw-bio\">plaquettes</span>), <span class=\"kw-etio\">++ enfant</span></li></ul><h4>Étiologies périphériques</h4><ul><li><span class=\"kw-etio\">PTI</span> ++ ; <span class=\"kw-etio\">viroses</span> (<span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHC</span>, EBV, CMV, Parvovirus B19)</li><li><span class=\"kw-etio\">Lupus / SAPL</span> ; <span class=\"kw-etio\">iatrogène</span> (<span class=\"kw-etio\">TIH</span>, quinine, thiazidiques)</li></ul><h4>PEC</h4><ul><li>PTI = <span class=\"kw-ci\">pas de transfusion plaquettaire systématique</span> (destruction périphérique), sauf hémorragie sévère</li></ul><h4>Renvoi</h4><ul><li>Item 214 (thrombopénie)</li></ul>"},{"id":"t-mat","kind":"terminal","label":"MAT (SHU / PTT)","color":"red","detail":"<h4>Triade</h4><ul><li><span class=\"kw-bio\">Thrombopénie</span> + <span class=\"kw-bio\">IRA</span> + <span class=\"kw-bio\">anémie hémolytique mécanique</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Schizocytes</span> au frottis ; <span class=\"kw-bio\">LDH ↑</span> ; <span class=\"kw-bio\">haptoglobine effondrée</span> ; <span class=\"kw-bio\">ADAMTS13</span> (PTT)</li></ul><h4>Drapeaux (enfant)</h4><ul><li>Atteinte <span class=\"kw-clinique\">rénale</span>, <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">diarrhée glairosanglante</span> (<span class=\"kw-etio\">E. coli O157:H7</span>)</li></ul><h4>À retenir</h4><ul><li><span class=\"kw-alerte\">2e urgence après le fulminans</span> chez l'enfant ; <span class=\"kw-bio\">créatininémie</span> + <span class=\"kw-imagerie\">bandelette urinaire</span> systématiques</li></ul>"},{"id":"q-palpable","kind":"decision","label":"Purpura infiltré / palpable ? — Palpation = clé du mécanisme vasculaire","branches":[{"to":"t-vascularite","label":"Infiltré · déclive · aggravé par l'orthostatisme","color":"amber"},{"to":"t-thrombotique","label":"Nécrotique + livedo racemosa","color":"red"},{"to":"t-fragilite","label":"Maculeux · non infiltré · chronique","color":"green"}]},{"id":"t-vascularite","kind":"terminal","label":"Purpura vasculaire (vascularite)","color":"amber","detail":"<h4>Aspect</h4><ul><li><span class=\"kw-clinique\">Purpura</span> <span class=\"kw-clinique\">polymorphe</span>, pétéchial, <span class=\"kw-clinique\">infiltré (palpable)</span>, déclive, par poussées</li></ul><h4>Signes extra-cutanés</h4><ul><li><span class=\"kw-clinique\">Arthralgies</span>, atteinte <span class=\"kw-clinique\">rénale</span> (glomérulopathie), <span class=\"kw-clinique\">neuropathie périphérique</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Purpura rhumatoïde (Schönlein-Henoch)</span> = cause la plus fréquente de <span class=\"kw-clinique\">purpura</span> infiltré de l'enfant</li><li><span class=\"kw-etio\">PAN, GPA, MPA, GEPA</span> ; <span class=\"kw-etio\">cryoglobulinémie</span> (→ <span class=\"kw-etio\">VHC</span>) ; <span class=\"kw-etio\">endocardite d'Osler</span> ; <span class=\"kw-etio\">lupus</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">protéinurie</span>, sédiment urinaire, <span class=\"kw-bio\">ANCA</span>, <span class=\"kw-bio\">cryoglobulinémie</span>, <span class=\"kw-bio\">EPP</span></li></ul><h4>Piège</h4><ul><li><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">vascularites des gros vaisseaux</span> (Horton, <span class=\"kw-clinique\">Takayasu</span>) ne donnent <span class=\"kw-alerte\">jamais</span> de <span class=\"kw-clinique\">purpura</span></li></ul><h4>Renvoi</h4><ul><li>Item 193 (<span class=\"kw-clinique\">vascularite</span> systémique) · Item 152 (<span class=\"kw-clinique\">endocardite</span> infectieuse)</li></ul>"},{"id":"t-thrombotique","kind":"terminal","label":"Purpura thrombotique","color":"red","detail":"<h4>Aspect</h4><ul><li><span class=\"kw-clinique\">Monomorphe</span>, forte <span class=\"kw-alerte\">composante nécrotique</span> (plaques &gt;<span class=\"kw-chiffre\"> 1 cm</span>), aigu ; <span class=\"kw-clinique\">livedo racemosa</span></li></ul><h4>Microthromboses</h4><ul><li><span class=\"kw-etio\">CIVD</span> ; <span class=\"kw-etio\">SAPL</span> (forme catastrophique = thromboses multiples + <span class=\"kw-alerte\">défaillance</span> multiviscérale)</li><li><span class=\"kw-etio\">Cryoglobulinémie</span> ; <span class=\"kw-etio\">SMP</span> ; déficit en protéine C/S ; <span class=\"kw-ttt\">AVK</span> / <span class=\"kw-ttt\">héparines</span></li></ul><h4>Embolies distales</h4><ul><li>Graisseuses (polytrauma) ; cristaux de <span class=\"kw-etio\">cholestérol</span> (<span class=\"kw-etio\">athérome</span>) ; cruoriques (cardiopathie emboligène)</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Hémostase</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">D-dimères</span>) → recherche de <span class=\"kw-alerte\">CIVD</span></li></ul><h4>Renvoi</h4><ul><li>Item 194 (<span class=\"kw-clinique\">lupus</span> - SAPL)</li></ul>"},{"id":"t-fragilite","kind":"terminal","label":"Fragilité vasculaire (purpura dermatologique)","color":"green","detail":"<h4>Aspect</h4><ul><li><span class=\"kw-clinique\">Ecchymotique</span>, chronique, <span class=\"kw-clinique\">non infiltré</span>, non déclive (zones de frottement)</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Purpura de Bateman</span> : face dorsale des avant-bras/mains ; hypercorticisme, sénescence cutanée</li><li><span class=\"kw-etio\">Scorbut</span> : <span class=\"kw-bio\">carence en vitamine C</span> → guérison par <span class=\"kw-ttt\">vitamine C</span> ; gingivorragies</li><li><span class=\"kw-etio\">Ehlers-Danlos</span> ; fragilité capillaire idiopathique (<span class=\"kw-clinique\">femme jeune</span>) ; capillarite chronique (insuffisance veineuse → dermite ocre)</li></ul><h4>À retenir</h4><ul><li>Pas de <span class=\"kw-alerte\">syndrome hémorragique</span> (sauf gingivorragies du scorbut), pas de <span class=\"kw-alerte\">signe de gravité</span></li></ul>"}]},"cards":[{"i":"3a18edda4f8b","n":215,"o":"215-1","u":"Définition","t":"Savoir définir et reconnaître un purpura","q":"Quelle est l'évolution colorimétrique typique d'une lésion purpurique ?","a":"<p>L'évolution d'une lésion purpurique, appelée biligénie locale, passe par les couleurs suivantes : <strong>rouge → violet-bleu → vert-jaune → chamois</strong>. La répétition de lésions au même endroit peut parfois laisser une dyschromie brunâtre (dermite ocre) ou des cicatrices blanchâtres.</p>"},{"i":"6a267489ec79","n":215,"o":"215-1","u":"Définition","t":"Savoir définir et reconnaître un purpura","q":"Quels sont les quatre types de purpura à distinguer selon l'aspect des lésions ?","a":"<ul><li><strong>Purpura pétéchial</strong> : Lésions punctiformes (<strong>1 à 4 mm</strong>), souvent aux membres inférieurs.</li><li><strong>Vibices</strong> : Lésions linéaires, le long des plis de flexion, zones de friction ou de traction.</li><li><strong>Purpura ecchymotique</strong> : Nappes bleu violacé aux contours mal limités (<strong>&gt; 1 cm</strong>).</li><li><strong>Purpura nécrotique</strong> : Pétéchies ou ecchymoses surélevées par une zone de nécrose.</li></ul>"},{"i":"804188d734ca","n":215,"o":"215-1","u":"Définition","t":"Savoir définir et reconnaître un purpura","q":"Quels sont les cinq traits sémiologiques clés permettant de reconnaître un purpura ?","a":"<ul><li><strong>Couleur</strong> : Lésions rouges ou violacées, séparées par un intervalle de peau saine.</li><li><strong>Vitropression</strong> : Ne s'efface <strong>pas à la vitropression</strong>, ce qui le distingue de l'érythème.</li><li><strong>Palpation</strong> : Maculeux (non palpable) ou palpable (infiltré).</li><li><strong>Taille</strong> : Variable, de la pétéchie punctiforme à la nappe ecchymotique.</li><li><strong>Évolution</strong> : Disparition sans séquelle en quelques jours, en passant par les couleurs de la biligénie locale.</li></ul>"},{"i":"dc3a4541feea","n":215,"o":"215-1","u":"Définition","t":"Savoir définir et reconnaître un purpura","q":"Quelle est la définition du purpura ?","a":"<p>Le purpura est une <strong>lésion cutanée ou muqueuse</strong> liée à une <strong>extravasation de sang</strong> dans le derme ou le chorion, spontanée ou consécutive à un traumatisme minime.</p>"},{"i":"f1f16654a318","n":215,"o":"215-1","u":"Définition","t":"Savoir définir et reconnaître un purpura","q":"Comment différencier cliniquement le purpura de l'érythème ?","a":"<p>La différence clinique décisive réside dans la <strong>vitropression</strong> : le purpura <strong>ne s'efface pas</strong> à la vitropression, tandis que l'érythème, qui est une dilatation vasculaire dermique, <strong>s'efface complètement</strong>.</p>"},{"i":"47c2daba1521","n":215,"o":"215-2","u":"Diagnostic positif","t":"Savoir différencier un purpura vasculaire d’un purpura thrombopénique","q":"Comment la nécrose et la topographie du purpura peuvent-elles aider à différencier un purpura thrombopénique d'un purpura vasculaire ?","a":"<ul><li>La <strong>nécrose</strong> est généralement absente dans un purpura thrombopénique, mais peut être présente voire une composante nette dans un purpura vasculaire.</li><li>La <strong>topographie</strong> d'un purpura thrombopénique est plutôt diffuse, prédominant en zones déclives. Pour un purpura vasculaire, la topographie est également déclive et aggravée par l'orthostatisme.</li></ul>"},{"i":"8412cbafdb77","n":215,"o":"215-2","u":"Diagnostic positif","t":"Savoir différencier un purpura vasculaire d’un purpura thrombopénique","q":"Quels signes extra-cutanés doivent faire évoquer un purpura vasculaire plutôt qu'un purpura thrombopénique ?","a":"<p>Devant un purpura, la présence de <strong>signes extra-cutanés</strong> tels que des <strong>arthralgies</strong>, une <strong>atteinte rénale</strong> ou une <strong>neuropathie</strong> doit fortement faire évoquer un purpura vasculaire. Ces signes sont absents en cas de purpura thrombopénique.</p>"},{"i":"b638dec79f1c","n":215,"o":"215-2","u":"Diagnostic positif","t":"Savoir différencier un purpura vasculaire d’un purpura thrombopénique","q":"Quelle est la principale distinction à établir devant un purpura pour orienter le diagnostic étiologique ?","a":"<p>La principale distinction à établir devant un purpura est entre un mécanisme <strong>hématologique</strong> (orientant vers une thrombopénie ou thrombopathie) et un mécanisme <strong>vasculaire</strong> (orientant vers une vascularite).</p>"},{"i":"c355818f413f","n":215,"o":"215-2","u":"Diagnostic positif","t":"Savoir différencier un purpura vasculaire d’un purpura thrombopénique","q":"Quel est le piège diagnostique classique concernant la palpation d'un purpura ?","a":"<p>Un piège classique est qu'un purpura <strong>infiltré et palpable</strong> oriente fortement vers une <strong>vascularite</strong> (mécanisme vasculaire), même en l'absence d'atteinte extra-cutanée. En revanche, un purpura thrombopénique reste <strong>maculeux</strong> (non palpable).</p>"},{"i":"c502756710f1","n":215,"o":"215-2","u":"Diagnostic positif","t":"Savoir différencier un purpura vasculaire d’un purpura thrombopénique","q":"Quels sont les éléments cliniques permettant de différencier un purpura thrombopénique d'un purpura vasculaire en termes d'aspect et de palpation ?","a":"<ul><li>Le purpura thrombopénique est typiquement <strong>monomorphe</strong> (pétéchial ou ecchymotique) et <strong>maculeux</strong> (non palpable).</li><li>Le purpura vasculaire (vascularite) est généralement <strong>polymorphe</strong>, aigu, par poussées, et <strong>infiltré</strong> (maculo-papuleux), donc palpable. Il peut s'accompagner de livedo réticulaire.</li></ul>"},{"i":"52a7a5ed2ddf","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Qu'est-ce qui caractérise un syndrome hémorragique sévère et en fait une urgence vitale absolue devant un purpura chez l'enfant ?","a":"<p>Un <strong>syndrome hémorragique sévère</strong>, urgence vitale absolue chez l'enfant quel que soit l'étiologie du purpura, est caractérisé par :</p><ul><li>Un saignement extériorisé actif</li><li>Un <strong>collapsus</strong></li><li>Une hémorragie viscérale</li></ul>"},{"i":"85651a6b5880","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Quels sont les drapeaux rouges des syndromes de CIVD / vascularites systémiques devant un purpura ?","a":"<p>Les syndromes de <strong>CIVD / vascularites systémiques</strong>, entraînant des microthromboses et une potentielle défaillance multiviscérale, peuvent être signalés par :</p><ul><li>Une composante nécrotique nette du purpura</li><li>Un <strong>livedo racemosa</strong></li><li>Un SAPL catastrophique (syndrome des antiphospholipides)</li></ul>"},{"i":"a3a19ca0ccd6","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Quels drapeaux cliniques doivent faire évoquer un MAT (Syndrome Hémolytique et Urémique) devant un purpura chez l'enfant ?","a":"<p>Devant un purpura chez l'enfant, un <strong>syndrome hémolytique et urémique (SHU)</strong> doit être évoqué face à :</p><ul><li>La triade classique : <strong>thrombopénie + insuffisance rénale aiguë (IRA) + anémie hémolytique</strong></li><li>Une atteinte rénale</li><li>Une hypertension artérielle (HTA)</li><li>Des antécédents de diarrhée récente glairo-sanglante (souvent liée à <em>E. coli O157:H7</em>)</li></ul>"},{"i":"ac7638c48d0e","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Quelle est la définition et les critères d'urgence du purpura fulminans devant un purpura ?","a":"<p>Le <strong>purpura fulminans</strong> est une urgence devant être reconnue immédiatement. Ses critères sont :</p><ul><li>Sepsis grave à méningocoque (le plus souvent)</li><li>Rapidement extensif</li><li>Présence d'au moins <strong>1 élément nécrotique ou ecchymotique de ≥ 3 mm</strong></li></ul>"},{"i":"b3a312dbc258","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Quelle définition donne-t-on à une thrombopénie profonde en cas de purpura, et quels sont les signes d'alerte associés ?","a":"<p>Une <strong>thrombopénie profonde</strong> est définie par un taux de plaquettes <strong>&lt; 20 G/L</strong> (souvent &lt; 10 G/L), indiquant un risque hémorragique majeur. Les signes d'alerte associés sont :</p><ul><li>Bulles hémorragiques intrabuccales</li><li>Gingivorragies spontanées</li><li>Hématurie macroscopique</li><li>Céphalées avec signes méningés (suggérant une hémorragie intracrânienne)</li><li>Syndrome anémique aigu</li></ul>"},{"i":"c37b9bb66d6a","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Quels sont les drapeaux rouges cliniques du purpura fulminans devant un purpura ?","a":"<p>Les drapeaux rouges du purpura fulminans, suggérant un sepsis grave, sont :</p><ul><li><strong>Fièvre élevée</strong></li><li>Frissons</li><li>Extrémités froides</li><li>Marbrures</li><li>Temps de recoloration cutanée (TRC) <strong>≥ 3 secondes</strong></li><li>Tachycardie</li><li>Hypotension</li></ul>"},{"i":"c872b1512102","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Chez l'enfant, quelle est la priorité diagnostique à éliminer devant tout purpura fébrile ?","a":"<p>Chez l'enfant, devant tout <strong>purpura fébrile</strong>, le diagnostic à éliminer en priorité est le <strong>purpura fulminans</strong>. L'injection <strong>IV/IM de C3G</strong> doit précéder toute autre prise en charge.</p>"},{"i":"deb80385d9ba","n":215,"o":"215-3","u":"Identifier une urgence","t":"Apprécier la gravité d’un purpura","q":"Quels drapeaux cliniques doivent faire évoquer une hémopathie maligne devant un purpura chez l'enfant ?","a":"<p>Devant un purpura chez l'enfant, il faut évoquer une <strong>hémopathie maligne</strong> (leucémie aiguë lymphoblastique/myéloïde, métastases médullaires) en présence des drapeaux cliniques suivants :</p><ul><li><strong>AEG récente</strong> (Altération de l'État Général)</li><li><strong>Syndrome tumoral</strong> (adénopathies, hépato-splénomégalie, douleurs osseuses)</li><li>Atteinte d'autres lignées sanguines (anémie, neutropénie fébrile)</li></ul>"},{"i":"2c64fe836e4a","n":215,"o":"215-4","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic de purpura fulminas","q":"Dans quelle situation la fièvre peut-elle être absente initialement en cas de purpura fulminans ?","a":"<p>La fièvre peut manquer initialement chez le <strong>sujet âgé</strong>, l'<strong>immunodéprimé</strong>, ou en tout début d'évolution. Cependant, la présence d'un <strong>purpura nécrotique extensif rapidement progressif</strong> doit faire évoquer le diagnostic même si la fièvre est absente.</p>"},{"i":"3be098f1d228","n":215,"o":"215-4","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic de purpura fulminas","q":"Quel est l'élément clinique clé permettant de diagnostiquer un purpura fulminans et d'agir en urgence ?","a":"<p>L'élément clé est la présence d'au moins <strong>un élément nécrotique ou ecchymotique dont la taille est égale ou supérieure à 3 mm</strong>. Ce purpura est rapidement extensif et ne s'efface pas à la vitropression. La seule présence de cet élément devant un purpura fébrile doit déclencher l'administration immédiate d'une <strong>C3G</strong>.</p>"},{"i":"5f447045d5ed","n":215,"o":"215-4","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic de purpura fulminas","q":"Quels sont les germes principalement responsables du purpura fulminans ?","a":"<ul><li>Principalement <strong><em>Neisseria meningitidis</em></strong> (méningocoque), surtout les sérogroupes B et C.</li><li>Plus rarement <em>Streptococcus pneumoniae</em> ou <em>Haemophilus influenzae</em> b.</li></ul>"},{"i":"889a847fdbe3","n":215,"o":"215-4","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic de purpura fulminas","q":"Quelle est la définition clinique du purpura fulminans ?","a":"<p>Le purpura fulminans est un <strong>sepsis grave</strong>, le plus souvent d'origine <strong>méningococcique</strong>, associant un <strong>purpura nécrotique extensif</strong> et un <strong>état de choc septique</strong>.</p>"},{"i":"e1891b2b3f2b","n":215,"o":"215-4","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic de purpura fulminas","q":"Quel est le pronostic du purpura fulminans ?","a":"<p>La mortalité du purpura fulminans est élevée, de l'ordre de <strong>20 à 30 %</strong>, et ce malgré l'antibiothérapie. Le pronostic dépend grandement du <strong>délai d'administration de la C3G</strong>.</p>"},{"i":"74cd4c65679e","n":215,"o":"215-5","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen clinique chez un patient porteur d’un purpura","q":"Comment caractériser les lésions purpuriques lors de l'examen clinique d'un patient ?","a":"<p>Lors de l'examen clinique, les lésions purpuriques doivent être caractérisées par :</p><ul><li>Leur <strong>topographie</strong>.</li><li>Leur <strong>aspect</strong> : <ul><li><strong>Pétéchial</strong> (petites taches punctiformes)</li><li><strong>Vibices</strong> (linéaires)</li><li><strong>Ecchymotique</strong> (plus grandes, en 'bleu')</li><li><strong>Nécrotique</strong> (avec nécrose tissulaire)</li></ul></li><li>Leur <strong>caractère</strong> : <ul><li><strong>Infiltré</strong> ( palpable, évoquant une vascularite)</li><li><strong>Maculeux</strong> (non palpable)</li></ul></li><li>La recherche de <strong>vitropression négative</strong> (le purpura ne s'efface pas à la pression).</li></ul>"},{"i":"785bfd7236c8","n":215,"o":"215-5","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen clinique chez un patient porteur d’un purpura","q":"Quels sont les éléments clés de l'anamnèse à rechercher systématiquement chez un patient présentant un purpura ?","a":"<p>Devant un purpura, l'anamnèse doit systématiquement rechercher les éléments suivants :</p><ul><li>Les <strong>antécédents familiaux</strong> de thrombopénie, thrombopathie ou pathologie dysimmunitaire (ex: lupus).</li><li>Le <strong>terrain du patient</strong> : âge, sexe, ethnie, épisodes antérieurs de signes hémorragiques.</li><li>Le <strong>contexte récent</strong> : infection virale, contage infectieux, séjour à l'étranger, prise médicamenteuse, statut vaccinal (pneumocoque, méningocoque) ou vaccin récent (ROR).</li><li>Les <strong>signes hémorragiques associés</strong> : épistaxis, gingivorragies, méno/métrorragies, hématurie, méléna, rectorragies.</li><li>Les <strong>signes d'orientation</strong> : fièvre, arthralgies, douleurs abdominales, douleurs osseuses, AEG, céphalées.</li></ul>"},{"i":"c45438b1fded","n":215,"o":"215-5","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen clinique chez un patient porteur d’un purpura","q":"Quels systèmes ou zones corporelles doivent être examinés spécifiquement en présence d'un purpura, en dehors des lésions cutanées ?","a":"<p>En dehors des lésions purpuriques cutanées, l'examen clinique doit être complet et inclure :</p><ul><li>Les <strong>muqueuses</strong> : recherche de bulles hémorragiques intrabuccales, gingivorragies, pétéchies palatines, conjonctives.</li><li>L'évaluation de l'<strong>hémodynamique</strong> : Pression Artérielle, Fréquence Cardiaque, Temps de Recoloration Cutanée, marbrures, extrémités froides.</li><li>La recherche d'un <strong>syndrome tumoral</strong> : adénopathies périphériques, hépato-splénomégalie, douleurs osseuses (sternum, métaphyses), masses.</li><li>La recherche de <strong>signes extra-cutanés</strong> : arthralgies, douleurs abdominales, réalisation d'une bandelette urinaire (hématurie, protéinurie), recherche de signes neurologiques.</li></ul>"},{"i":"d41039421df6","n":215,"o":"215-5","u":"Diagnostic positif","t":"Connaître les modalités de réalisation de l’examen clinique chez un patient porteur d’un purpura","q":"Quels sont les signes de gravité à rechercher lors de l'examen clinique d'un purpura ?","a":"<p>Les signes de gravité à rechercher impérativement chez un patient porteur d'un purpura sont :</p><ul><li>Un <strong>saignement extériorisé actif</strong> et important.</li><li>Un <strong>collapsus</strong> ou des signes d'instabilité hémodynamique (hypotension artérielle, tachycardie, marbrures, TRC allongé, extrémités froides).</li><li>Des <strong>troubles de la conscience</strong>.</li><li>Des <strong>céphalées associées à des signes méningés</strong>.</li></ul>"},{"i":"4205e2fe5e70","n":215,"o":"215-6","u":"Diagnostic positif","t":"Connaître les modalités de prescription des examens biologiques à effectuer en urgence devant un purpura","q":"Comment interpréter une numération plaquettaire devant un purpura ?","a":"<ul><li><strong>Plaquettes &lt; 30 G/L</strong> : La thrombopénie est imputable dans le purpura ; ne pas négliger une cause associée (thrombose, vascularite, embolie).</li><li><strong>Plaquettes entre 30 et 100 G/L</strong> : Évoquer une consommation de plaquettes par microthromboses diffuses (purpura thrombotique, CIVD).</li><li><strong>Plaquettes &gt; 100 G/L</strong> : La thrombopénie n'est pas imputable dans le purpura ; rechercher une autre cause (vascularite, embolie, thrombose).</li></ul>"},{"i":"6af23f98dc01","n":215,"o":"215-6","u":"Diagnostic positif","t":"Connaître les modalités de prescription des examens biologiques à effectuer en urgence devant un purpura","q":"Quel est le bilan biologique de première intention à réaliser systématiquement devant tout purpura ?","a":"<p>Devant tout purpura, le bilan biologique de première intention à réaliser systématiquement comprend :</p><ul><li>Une <strong>NFS-plaquettes avec frottis sanguin et réticulocytes</strong>.</li><li>Un <strong>bilan d'hémostase</strong> (TP, TCA, fibrinogène, D-dimères).</li><li>Un <strong>bilan hépatique</strong>.</li><li>Un <strong>groupe sanguin, Rhésus et RAI</strong>.</li><li>Une <strong>créatininémie et une bandelette urinaire</strong>.</li></ul>"},{"i":"6cd5709a49e6","n":215,"o":"215-6","u":"Diagnostic positif","t":"Connaître les modalités de prescription des examens biologiques à effectuer en urgence devant un purpura","q":"En cas de purpura, quelles informations un bilan d'hémostase (TP, TCA, fibrinogène, D-dimères) peut-il apporter ?","a":"<p>Un bilan d'hémostase permet de :</p><ul><li>Rechercher une <strong>coagulation intravasculaire disséminée (CIVD)</strong>.</li><li>Orienter vers une <strong>coagulopathie</strong> sous-jacente.</p></li></ul>"},{"i":"bff011d6c3c0","n":215,"o":"215-6","u":"Diagnostic positif","t":"Connaître les modalités de prescription des examens biologiques à effectuer en urgence devant un purpura","q":"Pourquoi réalise-t-on une NFS-plaquettes avec frottis sanguin et réticulocytes en urgence devant un purpura ?","a":"<p>Cet examen est fondamental pour :</p><ul><li><strong>Affirmer ou éliminer une thrombopénie</strong>.</li><li>Rechercher d'autres cytopénies associées.</li><li>Orienter vers une <strong>hémopathie</strong> ou une <strong>microangiopathie thrombotique (MAT)</strong>, notamment par la présence de <strong>schizocytes</strong>.</li></ul>"},{"i":"dc003c6fa9b7","n":215,"o":"215-6","u":"Diagnostic positif","t":"Connaître les modalités de prescription des examens biologiques à effectuer en urgence devant un purpura","q":"Pourquoi la recherche d'une atteinte rénale (créatininémie et bandelette urinaire) est-elle systématique devant un purpura, en particulier chez l'enfant ?","a":"<p>La recherche d'une atteinte rénale est systématique pour dépister :</p><ul><li>Une <strong>vascularite</strong>.</li><li>Une <strong>microangiopathie thrombotique (MAT)</strong>.</li></ul><p>Chez l'enfant, elle est particulièrement cruciale pour dépister le <strong>syndrome hémolytique et urémique (SHU)</strong>, qui est la <strong>2<sup>e</sup> urgence</strong> après le purpura fulminans.</p>"},{"i":"123178a5a0dc","n":215,"o":"215-8","u":"Étiologies","t":"Connaître les principales étiologies de purpura dont les causes infectieuses","q":"Quelle est la cause la plus fréquente de purpura infiltré chez l'enfant ?","a":"<p>La cause la plus fréquente de purpura infiltré chez l'enfant est le <strong>purpura rhumatoïde (Schönlein-Henoch)</strong>.</p>"},{"i":"28e138598e45","n":215,"o":"215-8","u":"Étiologies","t":"Connaître les principales étiologies de purpura dont les causes infectieuses","q":"Quelles sont les principales causes de purpura vasculaire d'origine infectieuse ?","a":"<ul><li><strong>Viroses graves</strong> : EBV, CMV, VIH, hépatites, dengue, Parvovirus B19, varicelle, rougeole.</li><li><strong>Sepsis</strong> chronique.</li><li><strong>Purpura fulminans</strong>.</li><li><strong>Rickettsioses</strong> (fièvre boutonneuse méditerranéenne).</li><li><strong>Paludisme</strong>.</li><li><strong>Endocardite d'Osler</strong> (avec purpura conjonctival et sus-claviculaire, nodules d'Osler, flammèches sous-unguéales).</li><li><strong>Maladie de Kawasaki</strong> (chez l'enfant).</li></ul>"},{"i":"cc802e8560b7","n":215,"o":"215-8","u":"Étiologies","t":"Connaître les principales étiologies de purpura dont les causes infectieuses","q":"Quelle est l'étiologie infectieuse à considérer en priorité devant tout purpura fébrile chez l'enfant ?","a":"<p>Devant tout purpura fébrile chez l'enfant, l'étiologie à considérer en priorité est le <strong>purpura fulminans</strong>, en raison de son caractère d'<strong>urgence vitale</strong>.</p>"},{"i":"d12b190d2ac9","n":215,"o":"215-8","u":"Étiologies","t":"Connaître les principales étiologies de purpura dont les causes infectieuses","q":"Quelles sont les principales causes infectieuses de thrombopénie (purpura hématologique) ?","a":"Les principales causes infectieuses de thrombopénie incluent :<ul><li><strong>Sepsis</strong> (mécanisme mixte : production et consommation).</li><li><strong>Paludisme</strong>.</li><li><strong>Viroses</strong> diverses entrainant une destruction immune : VIH, VHC, VHB, EBV, CMV, Parvovirus B19, rubéole.</li></ul>"},{"i":"0b14af3d44cb","n":215,"o":"215-9","u":"Prise en charge","t":"Connaître les mesures d’urgence devant un purpura","q":"Quand une transfusion de plaquettes est-elle indiquée en cas de syndrome hémorragique avec thrombopénie, en distinguant les thrombopénies centrales et périphériques ?","a":"<ul><li>Elle est indiquée en cas de <strong>thrombopénie centrale</strong>.</li><li>Elle n'est généralement <strong>pas indiquée en cas de thrombopénie périphérique</strong> (comme le Purpura Thrombopénique Immunologique - PTI), sauf en présence d'une <strong>hémorragie grave</strong> (neurologique, intra-abdominale, extériorisée abondante) ou en vue d'une <strong>chirurgie urgente</strong>. Le principal facteur pronostique est le retard d'antibiothérapie.</li></ul>"},{"i":"3578e196d160","n":215,"o":"215-9","u":"Prise en charge","t":"Connaître les mesures d’urgence devant un purpura","q":"Quelles sont les mesures d'urgence initiales face à un syndrome hémorragique sévère associé à une thrombopénie ?","a":"<ul><li><strong>Compression d'un saignement actif</strong>.</li><li>Pose de <strong>2 voies veineuses périphériques</strong>.</li><li>Réalisation d'un <strong>bilan prétransfusionnel</strong> (groupe sanguin effectué 2 fois, Rhésus, Recherche d'Agglutinines Irrégulières - RAI).</li></ul>"},{"i":"64ed03fb1e02","n":215,"o":"215-9","u":"Prise en charge","t":"Connaître les mesures d’urgence devant un purpura","q":"Quelle est la première mesure d'urgence à prendre en cas de suspicion de purpura fulminans, avant tout autre acte diagnostique ou thérapeutique ?","a":"<p>La première mesure est l'injection immédiate, par voie <strong>intramusculaire ou intraveineuse, d'une Céphalosporine de 3ème génération (C3G)</strong> (par exemple, ceftriaxone). Cette injection doit précéder toute ponction lombaire, hémoculture ou transfert.</p>"},{"i":"e7bc9b5e8521","n":215,"o":"215-9","u":"Prise en charge","t":"Connaître les mesures d’urgence devant un purpura","q":"Quelles sont les autres mesures d'urgence, en dehors de l'antibiothérapie, devant une suspicion de purpura fulminans ?","a":"<ul><li>Pose de <strong>2 voies veineuses périphériques</strong> de bon calibre, voire une voie intra-osseuse en cas d'échec.</li><li>Remplissage vasculaire par <strong>NaCl 0,9 % à 20 mL/kg en 5 à 10 minutes</strong>.</li><li><strong>Transfert médicalisé en réanimation</strong>.</li><li>Prophylaxie de l'entourage (rifampicine ou C3G IM) après confirmation diagnostique.</li></ul>"}]};